1259	export async function adminSuspendServer(serverId: string, suspend: boolean) {
1260	  const admin = await requireAdmin();
1261	  // Record WHY. An admin suspension is NOT an unpaid one: the renewal sweep skips
1262	  // suspended servers, so a paid-up customer suspended here is never charged and
1263	  // never warned — and before `suspendReason` existed, `terminateOverdue` then
1264	  // deleted their VM and all its data once the untouched term lapsed. Tagging it
1265	  // ADMIN keeps the terminator away from it and stops "Renew now" silently
1266	  // reversing an administrative decision.
1267	  await db.server.update({
1268	    where: { id: serverId },
1269	    data: suspend
1270	      ? { suspendReason: "ADMIN", suspendedNote: "suspended by support — contact us to restore access" }
1271	      : { suspendReason: null, suspendedNote: null },
1272	  });
1273	  await db.job.create({ data: { type: suspend ? "SUSPEND" : "UNSUSPEND", serverId } });
1274	  await audit(admin.id, suspend ? "admin.suspend_server" : "admin.unsuspend_server", serverId);
1275	  revalidatePath("/admin/servers");
1276	}
